-- Скелет = Clay … (21 кістка). neon — душа й примарне світло (Neon); alpha — напівпрозорі кольори (GolemBuilder v2). fx fade — GolemAnimator v3.6.
return {
 colors={bone="#3c414d",boneDark="#1f232b",silver="#a7b0bb",ghost="#3fd9c0",ghostSoft="#9fe3d8",glass="#a8efe6",soul="#5effd8",light="#f1f5f8",dark="#1c2836",pink="#f2a0b4",crypt="#596070",cryptDark="#2c3038"},
